package com.bankingax.core.reservation;
import com.bankingax.core.api.*; import com.bankingax.core.tool.*; import java.time.*; import java.util.*; import java.sql.Timestamp; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
@RestController @RequestMapping("/api/v1/reservations") @com.bankingax.core.persistence.ConditionalOnDataSource public class VisitReservationController {
 private final JdbcTemplate jdbc; private final InternalGatewayAuthenticator auth; private final StaffRankingPort ranking; /** Spec 3-3: change/cancel allowed only until 24 hours before the visit. */ static final Duration CHANGE_LOCK=Duration.ofHours(24);
 private final com.bankingax.core.notification.NotificationWriter notifications;
 public VisitReservationController(JdbcTemplate j,InternalGatewayAuthenticator a,StaffRankingPort r,org.springframework.beans.factory.ObjectProvider<com.bankingax.core.notification.NotificationWriter> n){jdbc=j;auth=a;ranking=r;notifications=n.getIfAvailable();}
 @PostMapping public ApiEnvelope<Item> create(@RequestHeader("X-Actor-Id")long actor,@RequestHeader("X-Actor-Role")ActorRole role,@RequestHeader("X-Tool-Gateway-Token")String token,@RequestBody Create q){customer(actor,role,token);return ApiEnvelope.success(q.requestId,"VISIT_RESERVATION",null,q.caseId,null,create(actor,q));}
 @GetMapping public ApiEnvelope<List<Item>> list(@RequestHeader("X-Actor-Id")long actor,@RequestHeader("X-Actor-Role")ActorRole role,@RequestHeader("X-Tool-Gateway-Token")String token,@RequestParam String requestId){customer(actor,role,token);return ApiEnvelope.success(requestId,"VISIT_RESERVATION",null,null,null,jdbc.query("select id,case_id,branch_id,assigned_staff_id,starts_at,status from visit_reservation where customer_id=? order by starts_at",(r,n)->row(r),actor));}
 @PostMapping("/{id}/cancel") public ApiEnvelope<Void> cancel(@PathVariable long id,@RequestHeader("X-Actor-Id")long actor,@RequestHeader("X-Actor-Role")ActorRole role,@RequestHeader("X-Tool-Gateway-Token")String token,@RequestParam String requestId){customer(actor,role,token);Timestamp lockAt=Timestamp.from(Instant.now().plus(CHANGE_LOCK)); if(jdbc.update("update visit_reservation set status='CANCELED',version=version+1 where id=? and customer_id=? and status in ('SELECTED','PENDING_ASSIGNMENT','CONFIRMED','NEEDS_MANUAL_ASSIGNMENT') and starts_at>?",id,actor,lockAt)==0){ Integer locked=jdbc.queryForObject("select count(*) from visit_reservation where id=? and customer_id=? and status<>'CANCELED' and starts_at<=?",Integer.class,id,actor,lockAt); if(locked!=null&&locked>0)throw new DomainException("RESERVATION_CHANGE_LOCKED","Reservations can only be changed or canceled until 24 hours before the visit."); throw new DomainException("NOT_FOUND","Reservation unavailable."); }return ApiEnvelope.success(requestId,"VISIT_RESERVATION",null,null,null,null);}
 @Transactional Item create(long customer,Create q){ var c=jdbc.query("select case_type,case_status,result_notified_at from service_case where id=? and customer_id=? for update",(r,n)->new Case(r.getString(1),r.getString(2),r.getTimestamp(3)),q.caseId,customer);if(c.isEmpty()||!"REVIEW_PASSED".equals(c.get(0).status)||c.get(0).notified==null)throw new DomainException("RESERVATION_NOT_ALLOWED","Staff PROCEED and customer notification are required."); if(q.startsAt==null||!q.startsAt.toInstant().isAfter(Instant.now()))throw new DomainException("INVALID_REQUEST","A future visit time is required.");
 Timestamp at=Timestamp.from(q.startsAt.toInstant());
 // Spring filters candidates (branch, active, not already booked at that time) and counts their current workload;
 // the ranking port only orders these candidates.
 List<StaffRankingPort.Candidate> candidates=jdbc.query("select u.id,(select count(*) from visit_reservation v where v.assigned_staff_id=u.id and v.status<>'CANCELED' and v.starts_at>=UTC_TIMESTAMP(6)) from `user` u where u.role='STAFF' and u.branch_id=? and u.is_active=true and not exists(select 1 from visit_reservation b where b.assigned_staff_id=u.id and b.status<>'CANCELED' and b.starts_at=?)",(r,n)->new StaffRankingPort.Candidate(r.getLong(1),r.getInt(2)),q.branchId,at);
 List<Long> ids=candidates.stream().map(StaffRankingPort.Candidate::staffId).toList();
 List<Long> ranked=q.staffId==null&&!ids.isEmpty()?ranking.rank(candidates,c.get(0).type):List.of();
 Long staff=q.staffId!=null?q.staffId:ranked.stream().filter(ids::contains).findFirst().orElse(null);
 if(staff==null)throw new DomainException("NEEDS_MANUAL_ASSIGNMENT","No eligible staff candidate.");
 if(!ids.contains(staff))throw new DomainException("FORBIDDEN","Staff is not eligible for the branch.");
 try{jdbc.update("insert into visit_reservation(case_id,customer_id,branch_id,assigned_staff_id,starts_at,status) values(?,?,?,?,?,'CONFIRMED')",q.caseId,customer,q.branchId,staff,at);}catch(org.springframework.dao.DataIntegrityViolationException e){throw new DomainException("RESERVATION_CONFLICT","Staff or case already has a reservation.",true);}
 Item item=jdbc.queryForObject("select id,case_id,branch_id,assigned_staff_id,starts_at,status from visit_reservation where case_id=? and status<>'CANCELED'",(r,n)->row(r),q.caseId);
 Long chosen=staff; int load=candidates.stream().filter(x->x.staffId()==chosen).mapToInt(StaffRankingPort.Candidate::activeAssignments).findFirst().orElse(0);
 jdbc.update("insert into event_log(entity_type,entity_id,event_type,from_value,to_value,actor_type,actor_id,request_id,payload) values('VISIT_RESERVATION',?,'VISIT_ASSIGNED',null,?,'SYSTEM',null,?,JSON_OBJECT('caseId',?,'basis','TASK_CODE_AND_WORKLOAD','candidateCount',?,'assignedWorkload',?,'recommended',?))",
   String.valueOf(item.id()),String.valueOf(chosen),q.requestId+"-assign",q.caseId,candidates.size(),load,ranked.isEmpty()?null:String.valueOf(ranked.get(0)));
 if(notifications!=null)notifications.store(customer,q.caseId,null,"VISIT_CONFIRMED","방문 예약이 확정되었어요","방문 예약과 담당 직원 배정이 완료되었어요. 방문 24시간 전까지 변경·취소할 수 있어요. 예약은 예금 지급 확정이 아니에요.","visit-confirmed-"+item.id());
 return item;}
 private void customer(long a,ActorRole r,String t){auth.verify(t);if(r!=ActorRole.CUSTOMER)throw new DomainException("FORBIDDEN","Customer access is required.");} private static Item row(java.sql.ResultSet r)throws java.sql.SQLException{return new Item(r.getLong(1),r.getLong(2),r.getLong(3),r.getLong(4),r.getTimestamp(5).toInstant(),r.getString(6));} private record Case(String type,String status,java.sql.Timestamp notified){} public record Create(String requestId,long caseId,long branchId,Long staffId,OffsetDateTime startsAt){} public record Item(long id,long caseId,long branchId,long staffId,Instant startsAt,String status){}
}
